// The practice CLI before the Intermediate capstone repair. Kept as a
// fixture so the check must detect the original crash and an uncommitted fix.
export const buggyApp = {
  "src/check-links.js": "import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';\nimport { dirname, join, relative } from 'node:path';\nimport { findLinks, isExternal } from './links.js';\n\nfunction markdownFiles(root, entry) {\n  const path = join(root, entry);\n  if (!existsSync(path)) return [];\n  if (statSync(path).isFile()) return path.endsWith('.md') ? [path] : [];\n  return readdirSync(path)\n    .filter((name) => !name.startsWith('.') && name !== 'node_modules')\n    .flatMap((name) => markdownFiles(root, join(entry, name)));\n}\n\n// Returns every relative link whose target file does not exist.\nexport function brokenLinks(root, config) {\n  const broken = [];\n  const files = [...new Set(config.files.flatMap((entry) => markdownFiles(root, entry)))].sort();\n  for (const file of files) {\n    for (const link of findLinks(readFileSync(file, 'utf8'))) {\n      const target = link.target.split('#')[0];\n      if (!target || isExternal(link.target)) continue;\n      if (config.ignore.some((prefix) => link.target.startsWith(prefix))) continue;\n      if (!existsSync(join(dirname(file), decodeURIComponent(target)))) {\n        broken.push({ file: relative(root, file), line: link.line, target: link.target });\n      }\n    }\n  }\n  return broken;\n}\n",
  "src/cli.js": "#!/usr/bin/env node\n// Checks the relative links in a folder's Markdown files.\n//   node src/cli.js [folder]\nimport { existsSync, readFileSync } from 'node:fs';\nimport { join, resolve } from 'node:path';\nimport { parseConfig, DEFAULTS } from './config.js';\nimport { brokenLinks } from './check-links.js';\n\nconst root = resolve(process.argv[2] ?? '.');\nconst configPath = join(root, 'linkcheck.json');\nlet config = DEFAULTS;\ntry {\n  if (existsSync(configPath)) config = parseConfig(readFileSync(configPath, 'utf8'));\n} catch (error) {\n  console.error(`linkcheck: ${error.message}`);\n  process.exit(2);\n}\n\nconst broken = brokenLinks(root, config);\nfor (const b of broken) console.log(`${b.file}:${b.line}: broken link to ${b.target}`);\nconsole.log(broken.length ? `${broken.length} broken link(s)` : 'All relative links resolve.');\nprocess.exit(broken.length ? 1 : 0);\n",
  "src/config.js": "// Parses linkcheck.json. Every field is optional:\n//   files:  files or folders to scan for Markdown links (default [\".\"])\n//   ignore: link targets to skip, matched as prefixes (default [])\nexport const DEFAULTS = { files: ['.'], ignore: [] };\n\nexport function parseConfig(text) {\n  const raw = JSON.parse(text);\n  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {\n    throw new Error('linkcheck.json must hold a JSON object');\n  }\n  const config = { ...DEFAULTS, ...raw };\n  for (const key of ['files', 'ignore']) {\n    if (!Array.isArray(config[key]) || !config[key].every((v) => typeof v === 'string')) {\n      throw new Error(`linkcheck.json: \"${key}\" must be a list of strings`);\n    }\n  }\n  return config;\n}\n",
  "src/links.js": "// Finds inline Markdown links, [text](target), outside code blocks.\nexport function findLinks(markdown) {\n  const links = [];\n  let inFence = false;\n  markdown.split('\\n').forEach((line, i) => {\n    if (/^\\s*(```|~~~)/.test(line)) {\n      inFence = !inFence;\n      return;\n    }\n    if (inFence) return;\n    const prose = line.replace(/`[^`]*`/g, '');\n    for (const m of prose.matchAll(/(?<!!)\\[([^\\]]*)\\]\\(([^)\\s]+)\\)/g)) {\n      links.push({ text: m[1], target: m[2], line: i + 1 });\n    }\n  });\n  return links;\n}\n\nexport function isExternal(target) {\n  return /^[a-z][a-z0-9+.-]*:/i.test(target);\n}\n"
};

export const fixedApp = {
  ...buggyApp,
  'src/check-links.js': buggyApp['src/check-links.js'].replace(
    "      if (!existsSync(join(dirname(file), decodeURIComponent(target)))) {",
    "      let decoded;\n      try { decoded = decodeURIComponent(target); } catch { decoded = null; }\n      if (decoded === null || !existsSync(join(dirname(file), decoded))) {"),
};
